mapper.select:
SELECT COUNT(task.task_type)
FROM task, empgroup_emp
WHERE empgroup_emp.emp_id = #{empId}
  AND empgroup_emp.group_id = task.group_id
  AND task_type = #{type}

SELECT COUNT(fert_water.num)
FROM task, empgroup_emp, fert_water
WHERE empgroup_emp.emp_id = #{empId}
  AND empgroup_emp.group_id = task.group_id
  AND fert_water.brand = #{pesticideType}
  AND fert_water.tree_id = task.tree_id

SELECT task.*
FROM task
         INNER JOIN area_info ON task.area_id = area_info.id
         INNER JOIN employee ON area_info.emp_id = employee.id
WHERE task.orchard_id = #{orchardId}
  AND employee.id = #{empId}
  AND task_type = #{type}
  AND task.status = 1

SELECT orchard.name
FROM orchard
WHERE orchard.id = #{orchardId}

SELECT employee.name
FROM employee
WHERE id = #{receiverId}

SELECT report.*
FROM fruit.report
WHERE report.id = #{reportId}

SELECT COUNT(id)
FROM fruit.task
WHERE task_type = #{type}
